from __future__ import annotations

from app.platform.ui.founder_dashboard_stable import render_stable_founder_dashboard


BR_UI_08_STYLE = """
.br-shell{max-width:1500px;margin:0 auto;display:grid;grid-template-columns:minmax(0,1fr) 292px;gap:14px;height:calc(100vh - 114px)}
.br-main{display:flex;flex-direction:column;min-height:0;padding:0;overflow:hidden;border-radius:20px}.br-head{padding:16px 20px;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;gap:12px;background:linear-gradient(180deg,rgba(15,27,49,.96),rgba(8,15,29,.74))}.br-head h2{margin:0;font-size:22px;letter-spacing:-.02em}.br-actions{display:flex;gap:8px;flex-wrap:wrap}.br-chip{display:inline-flex;align-items:center;border:1px solid #263a5c;background:#081426;border-radius:999px;padding:5px 9px;color:#bdd2f4;font-size:11px;margin:8px 6px 0 0}.br-chip.live:before{content:'●';color:#22c55e;margin-right:6px}.br-history{display:none;border-bottom:1px solid var(--line);padding:14px 16px;background:#07101e}.br-history.open{display:block}.br-history input{border-radius:10px;padding:9px}.br-history-row{display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:8px;max-height:240px;overflow:auto;margin-top:10px}.br-session{border:1px solid #263a5c;background:#0b1628;border-radius:12px;padding:10px;color:#dbeafe;text-align:left}.br-session.active{border-color:#7c3aed;background:#111a31}.br-session-title{font-weight:850;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.br-session small{display:block;color:#94a3b8;margin-top:4px}.br-session-tools{display:flex;gap:6px;margin-top:8px}.br-session-tools button{font-size:11px;padding:5px 7px;border-radius:8px}.br-thread{flex:1;overflow:auto;padding:24px 30px 22px;display:flex;flex-direction:column;gap:18px;background:radial-gradient(circle at 50% 0,rgba(29,78,216,.08),transparent 28%),#050b15;scroll-behavior:smooth}.br-msg{display:grid;grid-template-columns:38px minmax(0,1fr);gap:12px;max-width:900px;animation:brfade .22s ease-out}.br-msg.user{align-self:flex-end;grid-template-columns:minmax(0,1fr) 38px;max-width:720px}.br-avatar{width:38px;height:38px;border-radius:13px;display:grid;place-items:center;font-weight:900;background:#13233d;color:#dbeafe;border:1px solid var(--line)}.br-msg.user .br-avatar{grid-column:2;background:linear-gradient(135deg,#f59e0b,#fef3c7);color:#111827}.br-content{min-width:0;display:flex;flex-direction:column}.br-name{font-size:12px;font-weight:850;color:#9fb4d8;margin:0 0 6px;display:flex;gap:8px;align-items:center;justify-content:space-between}.br-msg.user .br-name{justify-content:flex-end}.br-time{font-weight:500;color:#64748b}.br-bubble{border:1px solid var(--line);border-radius:17px;padding:14px 16px;line-height:1.48;white-space:pre-wrap;background:#091426;color:#e6efff;box-shadow:0 12px 34px rgba(0,0,0,.14);max-width:100%}.br-msg.user .br-bubble{background:#102846;border-color:#28558f;color:#f8fbff}.br-copy{align-self:flex-end;margin-top:5px;border:0;background:transparent;color:#7da4dc;font-size:11px;padding:0 2px;opacity:.72}.br-copy:hover{opacity:1;text-decoration:underline}.br-card{border:1px solid #7c3aed;background:linear-gradient(180deg,#111a31,#0a1324);border-radius:16px;padding:13px 14px;margin-top:10px;box-shadow:0 0 0 1px rgba(124,58,237,.12),0 20px 44px rgba(0,0,0,.22);max-width:860px}.br-card h3{margin:4px 0 6px;font-size:16px}.br-card-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:11px}.br-composer{border-top:1px solid var(--line);padding:12px;background:#07101e;display:grid;grid-template-columns:minmax(0,1fr) auto;gap:10px}.br-composer textarea{min-height:54px;max-height:170px;border-radius:16px;padding:15px;resize:vertical}.br-composer .primary{min-width:72px;border-radius:16px}.br-side{height:calc(100vh - 114px);position:sticky;top:22px;overflow:auto;border-radius:18px}.br-side h2{font-size:18px;margin:4px 0 12px}.br-mini{border:1px solid var(--line);background:#07101e;border-radius:14px;padding:12px;margin-bottom:9px}.br-mini strong{display:block;font-size:11px;text-transform:uppercase;letter-spacing:.07em;color:#93c5fd;margin-bottom:5px}.br-mini .value{font-weight:850;color:#f8fbff}.br-mini ul{padding-left:18px;margin:6px 0 0}.br-md h1{font-size:21px;margin:6px 0 18px}.br-md h2{font-size:18px;margin:18px 0 8px}.br-md h3{font-size:16px;margin:14px 0 7px}.br-md ul,.br-md ol{margin:7px 0 10px;padding-left:20px}.br-md li{margin:4px 0}.br-md code{background:#020817;border:1px solid #1e293b;border-radius:6px;padding:1px 5px}.br-md pre{background:#020817;border:1px solid #1e293b;border-radius:12px;padding:12px;overflow:auto;white-space:pre}.br-thinking .br-bubble:after{content:'  ● ● ●';letter-spacing:2px;color:#93c5fd;animation:brpulse 1s infinite}.br-hidden-modal #boardModal{display:none!important}@keyframes brpulse{50%{opacity:.35}}@keyframes brfade{from{opacity:0;transform:translateY(7px)}to{opacity:1;transform:translateY(0)}}@media(max-width:1100px){.br-shell{grid-template-columns:1fr;height:auto}.br-side{height:auto;position:relative}.br-msg,.br-msg.user{max-width:100%;grid-template-columns:1fr}.br-avatar{display:none}.br-thread{padding:20px}}
"""


BR_UI_08_SCRIPT = r"""
<script>
(function(){
  var STORE='br_ui_sessions_v2';
  var active=null;
  function id(x){return document.getElementById(x)}
  function auth(){return localStorage.getItem('mission_control_token')||''}
  function save(items){localStorage.setItem(STORE,JSON.stringify(items.slice(0,30)))}
  function sessions(){try{return JSON.parse(localStorage.getItem(STORE)||'[]')}catch(e){return[]}}
  function esc(s){return String(s||'').replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})}
  function time(){return new Date().toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'})}
  function md(t){var s=esc(t);s=s.replace(/```([\s\S]*?)```/g,function(_,c){return '<pre><code>'+c+'</code></pre>'});s=s.replace(/^### (.*)$/gm,'<h3>$1</h3>').replace(/^## (.*)$/gm,'<h2>$1</h2>').replace(/^# (.*)$/gm,'<h1>$1</h1>');s=s.replace(/\*\*(.*?)\*\*/g,'<strong>$1</strong>').replace(/`([^`]+)`/g,'<code>$1</code>');return s.replace(/\n/g,'<br>')}
  function label(k){return String(k||'').split('_').map(function(x){return x.charAt(0).toUpperCase()+x.slice(1)}).join(' ')}
  function persist(){if(!active)return;active.updated_at=new Date().toISOString();var xs=sessions().filter(function(s){return s.id!==active.id});xs.unshift(active);save(xs);renderHistory()}
  function post(url,body){return fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}).then(function(r){return r.json()})}
  function ensure(){var board=id('board');if(!board||board.dataset.br08)return;board.dataset.br08='1';board.innerHTML="<div class='br-shell'><section class='card br-main'><div class='br-head'><div><div class='brand-small'>Board Room</div><h2>Executive Workspace</h2><p class='muted'>A CEO-grade conversation for strategy, architecture, governance, and execution.</p><span class='br-chip live'>Runtime Constitution loaded</span><span class='br-chip'>Founder approval enforced</span><span class='br-chip'>Premium polish</span></div><div class='br-actions'><button class='secondary' onclick='toggleHistory()'>History</button><button class='secondary' onclick='newBoardChat()'>New Chat</button></div></div><div id='brHistory' class='br-history'><input id='brSearch' placeholder='Search conversations...' oninput='renderHistory()'><div id='brHistoryRow' class='br-history-row'></div></div><div id='brThread' class='br-thread'></div><div class='br-composer'><textarea id='message' placeholder='Message the Board Room...'></textarea><button id='boardBtn' class='primary' onclick='boardRoomChat()'>Send</button></div></section><aside class='card br-side'><div class='brand-small'>Executive Brief</div><h2>Live Signal</h2><div class='br-mini'><strong>Intent</strong><div id='conversationMode' class='value'>General Conversation</div><p id='modeDescription' class='muted'>No message yet.</p></div><div class='br-mini' id='executiveDecisionCard'><strong>Recommended Action</strong><div class='value'>None yet</div><p class='muted'>Send a message first.</p></div><div class='br-mini'><strong>Decisions</strong><ul id='decisionMinutes'><li>No decisions captured yet.</li></ul></div><div class='br-mini'><strong>Actions</strong><ul id='actionMinutes'><li>No actions captured yet.</li></ul></div><div class='br-mini'><strong>Knowledge</strong><ul id='knowledgeMinutes'><li>Important context will appear here.</li></ul></div><div class='br-mini' id='workflowCard'><strong>Current Mission</strong><div class='value'>None</div><p class='muted'>Workflow appears after approval.</p></div><p id='meetingMeta' class='muted'>No meeting yet.</p></aside></div>";newBoardChat();var m=id('message');if(m)m.addEventListener('keydown',function(e){if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();boardRoomChat()}})}
  function thread(){ensure();return id('brThread')}
  window.newBoardChat=function(){var box=id('brThread')||thread();box.innerHTML="<div class='br-card'><h3>Welcome back, Toni.</h3><p class='muted'>Tell me what to review, decide, or build. I will recommend execution only when it is appropriate.</p></div>";active={id:'S'+Date.now(),title:'New Board Room chat',messages:[],created_at:new Date().toISOString(),updated_at:new Date().toISOString()};renderHistory()}
  function add(role,text,decision,skip){var box=thread();if(box.querySelector('.br-card'))box.innerHTML='';var row=document.createElement('div');row.className='br-msg '+(role==='user'?'user':'board');var av=document.createElement('div');av.className='br-avatar';av.textContent=role==='user'?'TT':'AI';var c=document.createElement('div');c.className='br-content';var h=document.createElement('div');h.className='br-name';h.innerHTML=(role==='user'?'You':'Board Room')+' <span class="br-time">'+time()+'</span>';var b=document.createElement('div');b.className='br-bubble br-md';b.innerHTML=role==='user'?esc(text):md(text);var cp=document.createElement('button');cp.className='br-copy';cp.textContent='Copy';cp.onclick=function(){navigator.clipboard&&navigator.clipboard.writeText(text);cp.textContent='Copied';setTimeout(function(){cp.textContent='Copy'},1200)};c.appendChild(h);c.appendChild(b);c.appendChild(cp);if(decision&&decision.primary_action)c.appendChild(actionCard(decision));if(role==='user'){row.appendChild(c);row.appendChild(av)}else{row.appendChild(av);row.appendChild(c)}box.appendChild(row);box.scrollTop=box.scrollHeight;if(active&&!skip){active.messages.push({role:role,text:text,at:new Date().toISOString()});if(role==='user'&&active.messages.length===1)active.title=text.slice(0,64);persist()}return row}
  function actionCard(decision){var a=decision.primary_action||{};var card=document.createElement('div');card.className='br-card';card.innerHTML='<div class="small">Recommended next step</div><h3>'+esc(a.label||label(a.key))+'</h3><p class="muted">'+esc(decision.reason||'Recommended by Board Room.')+'</p><div class="br-card-actions"><button class="primary" onclick="createWorkflow()">Create Engineering Proposal</button><button class="secondary" onclick="addInlineNote()">Continue Discussion</button></div>';return card}
  window.addInlineNote=function(){add('board','Continue discussion selected.',null)}
  function setList(name,items,empty){var el=id(name);if(!el)return;el.innerHTML='';(items&&items.length?items:[empty]).slice(0,5).forEach(function(x){var li=document.createElement('li');li.textContent=x;el.appendChild(li)})}
  function renderCI(ci,meeting){if(!ci)return;id('conversationMode').textContent=ci.mode||'General Conversation';id('modeDescription').textContent=ci.recommended_next_action||'Review conversation.';setList('decisionMinutes',ci.decisions,'No decisions captured yet.');setList('actionMinutes',ci.actions,'No actions captured yet.');setList('knowledgeMinutes',ci.knowledge,'Important context will appear here.');id('meetingMeta').textContent=meeting||'No meeting yet.'}
  function renderDecision(d){var el=id('executiveDecisionCard');if(!d||!d.primary_action){el.innerHTML='<strong>Recommended Action</strong><div class="value">None yet</div><p class="muted">Send a message first.</p>';return}var a=d.primary_action;el.innerHTML='<strong>Recommended Action</strong><div class="value">'+esc(a.label||label(a.key))+'</div><p class="muted">'+esc(d.reason||'Recommended by Board Room.')+'</p>'}
  window.boardRoomChat=async function(){var m=id('message'),text=(m.value||'').trim();if(!text)return;id('boardBtn').disabled=true;add('user',text,null);m.value='';var thinking=add('board','Analyzing request… checking governance and safest next action.',null,true);thinking.classList.add('br-thinking');try{var data=await post('/mission-control/operating-console/chat',{token:auth(),message:text});thinking.remove();renderCI(data.conversation_intelligence,'Meeting ID: '+(data.meeting_id||''));renderDecision(data.executive_decision);add('board',data.board_room_response||JSON.stringify(data,null,2),data.executive_decision)}catch(e){thinking.remove();add('board','Board Room request failed: '+e,null)}finally{id('boardBtn').disabled=false;m.focus()}}
  window.createWorkflow=async function(){add('user','Create engineering proposal',null);try{var body=Array.from(document.querySelectorAll('#brThread .br-bubble')).map(function(x){return x.textContent}).join('\n');var data=await post('/mission-control/operating-console/workflow',{token:auth(),action:'create-proposal',message:body});renderCI(data.conversation_intelligence,'Workflow generated');if(data.founder_workflow){id('workflowCard').innerHTML='<strong>Current Mission</strong><div class="value">'+esc(data.founder_workflow.title)+'</div><p class="muted">'+esc(data.founder_workflow.status)+'</p>';add('board','Workflow created. Review it from the workflow card.',null)}else add('board','Workflow request completed.',null)}catch(e){add('board','Workflow request failed: '+e,null)}}
  window.renderHistory=function(){var row=id('brHistoryRow');if(!row)return;var q=(id('brSearch')&&id('brSearch').value||'').toLowerCase();row.innerHTML='';sessions().filter(function(s){return !q||(s.title||'').toLowerCase().indexOf(q)>=0}).forEach(function(s){var x=document.createElement('div');x.className='br-session '+(active&&s.id===active.id?'active':'');x.innerHTML='<div class="br-session-title">'+esc(s.title||'Untitled')+'</div><small>'+(s.messages||[]).length+' messages</small><div class="br-session-tools"><button onclick="loadSession(\''+s.id+'\')">Open</button><button onclick="deleteSession(\''+s.id+'\')">Delete</button></div>';row.appendChild(x)});if(!row.innerHTML)row.innerHTML='<span class="muted">No sessions yet.</span>'}
  window.loadSession=function(sid){var s=sessions().find(function(x){return x.id===sid});if(!s)return;active=JSON.parse(JSON.stringify(s));var box=thread();box.innerHTML='';(s.messages||[]).forEach(function(m){add(m.role,m.text,null,true)});id('brHistory').classList.remove('open')}
  window.deleteSession=function(sid){save(sessions().filter(function(s){return s.id!==sid}));if(active&&active.id===sid)newBoardChat();renderHistory()}
  window.toggleHistory=function(){ensure();id('brHistory').classList.toggle('open');renderHistory()}
  window.openBoardRoom=function(){ensure();if(window.showSection)window.showSection('board')}
  window.startCommand=function(){ensure();if(window.showSection)window.showSection('board');var c=id('commandInput'),m=id('message');if(c&&m)m.value=c.value||''}
  document.addEventListener('keydown',function(e){if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();toggleHistory()}});
  document.addEventListener('DOMContentLoaded',function(){document.body.classList.add('br-hidden-modal');ensure()});
})();
</script>
"""


def render_board_chat_dashboard() -> str:
    html = render_stable_founder_dashboard()
    html = html.replace("</style>", BR_UI_08_STYLE + "\n</style>")
    html = html.replace("</body>", BR_UI_08_SCRIPT + "\n</body>")
    return html
